import os, subprocess, threading, time, sys, glob

def run(args, stdin=b"", timeout=15, env_extra=None):
    base = "/tmp/fifo_%d" % os.getpid()
    for s in ("out","err"):
        try: os.unlink(base+s)
        except: pass
    os.mkfifo(base+"out"); os.mkfifo(base+"err")
    env=dict(os.environ); env["TERM"]="xterm"
    if env_extra: env.update(env_extra)
    fo = open(base+"out", "rb+")
    fe = open(base+"err", "rb+")
    events=[]
    def reader(f, name):
        while True:
            d = f.read(1)
            if not d: break
            events.append((time.time(), name, d))
    t1=threading.Thread(target=reader, args=(fo,"out")); t2=threading.Thread(target=reader, args=(fe,"err"))
    t1.start(); t2.start()
    try:
        p = subprocess.run(["/workspace/executable"]+args, input=stdin, env=env, stdout=open(base+"out","wb"), stderr=open(base+"err","wb"), timeout=timeout)
        rc = p.returncode
    except subprocess.TimeoutExpired:
        rc = "TO"
    time.sleep(0.3)
    for t in (t1,t2): t.join()
    fo.close(); fe.close()
    # merge per stream
    res = {"out":b"", "err":b""}
    for t,n,d in events: res[n]+=d
    for s in ("out","err"):
        try: os.unlink(base+s)
        except: pass
    return rc, res["out"], res["err"]
