pub fn parse(data: &[u8]) -> Option<TermInfo> {
    if data.len() < 12 { return None }
    let magic = u16::from_le_bytes([data[0], data[1]]);
    let (numsize, numfmt) = match magic {
        0o432 => (2usize, "h"),
        0o1036 => (4usize, "i"),
        _ => return None,
    };
    let names_size = u16::from_le_bytes([data[2], data[3]]) as usize;
    let bool_count = u16::from_le_bytes([data[4], data[5]]) as usize;
    let num_count = u16::from_le_bytes([data[6], data[7]]) as usize;
    let str_count = u16::from_le_bytes([data[8], data[9]]) as usize;
    let table_size = u16::from_le_bytes([data[10], data[11]]) as usize;
    let mut pos = 12;
    let names_end = pos + names_size; // names
    pos = names_end;
    let bools: Vec<bool> = data[pos..pos+bool_count].iter().map(|&b| b != 0).collect();  // hmm, 0=false, 1=true, 2=cancel?
    pos += bool_count;
    if (12 + names_size + bool_count) % 2 == 1 { pos += 1; }
    let mut numbers = Vec::with_capacity(num_count);
    for i in 0..num_count {
        let off = pos + i*numsize;
        if off + numsize > data.len() { return None }
        let v = if numsize == 2 { u16::from_le_bytes([data[off], data[off+1]]) as i64 }
                else { u32::from_le_bytes([data[off],data[off+1],data[off+2],data[off+3]]) as i64 };
        numbers.push(v);
    }
    pos += num_count * numsize;
    let mut offsets = Vec::with_capacity(str_count);
    for i in 0..str_count {
        let off = pos + i*2;
        if off + 2 > data.len() { return None }
        offsets.push(i16::from_le_bytes([data[off], data[off+1]]) as i32);
    }
    pos += str_count * 2;
    let table = &data[pos..pos+table_size];  // hmm, bounds check
    let mut strings = Vec::with_capacity(str_count);
    for off in offsets {
        if off < 0 || off as usize >= table.len() { strings.push(None); continue }
        let start = off as usize;
        let end = table[start..].iter().position(|&b| b == 0).map(|p| start+p).unwrap_or(table.len());
        strings.push(Some(table[start..end].to_vec()));
    }
