fn get_dbpath_for_term(term: &str) -> Option<PathBuf> {
    let first_char = term.chars().next()?;
    let mut dirs = Vec::new();
    if let Some(dir) = env::var_os("TERMINFO") { dirs.push(PathBuf::from(dir)); }
    if let Ok(dirs_str) = env::var("TERMINFO_DIRS") {
        for i in dirs_str.split(':') {
            match i {
                "" => dirs.push(PathBuf::from("/usr/share/terminfo")),
                "false" => continue,
                i => dirs.push(PathBuf::from(i)),
            }
        }
    }
    if let Ok(home) = env::var("HOME") { dirs.push(PathBuf::from(home).join(".terminfo")); }
    dirs.push(PathBuf::from("/usr/share/terminfo"));
    dirs.push(PathBuf::from("/lib/terminfo"));
    dirs.push(PathBuf::from("/usr/share/lib/terminfo"));
    for mut p in dirs {
        if fs::metadata(&p).is_ok() {
            p = p.join(first_char.to_string()).join(term);
            if fs::metadata(&p).is_ok() { return Some(p) }
            p.set_file_name(format!("{:x}", term.as_bytes()[0]));
            if fs::metadata(&p).is_ok() { return Some(p) }
        }
    }
    None
}
