fn get_dbpath_for_term(term: &str) -> Option<PathBuf> {
    let first_char = term.chars().next()?;
    let mut dirs = Vec::new();
    if let Some(dir) = env::var_os("TERMINFO") { dirs.push(PathBuf::from(dir)); }
