                j += 1;
                i = j;
                let v = pop!();
                let body = &spec_str[1..spec_str.len() - 1];
                let mut width = 0usize;
                let mut precision: Option<usize> = None;
                let mut left = false;
                let mut zeropad = false;
                let mut plus = false;
                let mut space = false;
                let mut alt = false;
                let mut it = body.chars().peekable();
                while let Some(ch) = it.next() {
                    match ch {
                        '-' => left = true,
                        '0' => zeropad = true,
                        '+' => plus = true,
                        ' ' => space = true,
                        '#' => alt = true,
                        ':' => {}
                        _ => break,
                    }
                }
                let mut numstr = String::new();
                for ch in it {
                    if ch == '.' {
                        let mut d = String::new();
                        for c2 in it.by_ref() {
                            d.push(c2);
                        }
                        precision = d.parse::<usize>().ok();
                        break;
                    }
                    numstr.push(ch);
                }
                width = numstr.parse::<usize>().unwrap_or(0);
                let mut s = match last {
                    b'd' => {
                        let mut t = v.abs().to_string();
                        if v < 0 {
                            t.insert(0, '-');
                        } else if plus {
                            t.insert(0, '+');
                        } else if space {
                            t.insert(0, ' ');
                        }
                        if zeropad && !left {
                            let sign_len = if t.starts_with('-') || t.starts_with('+') { 1 } else { 0 };
                            while t.len() < width {
                                t.insert(sign_len, '0');
                            }
                        }
                        t
                    }
                    b'c' => ((v & 0xff) as u8 as char).to_string(),
                    b'x' => format!("{:x}", v),
                    b'X' => format!("{:X}", v),
                    b'o' => format!("{:o}", v),
                    _ => v.to_string(),
                };
                if let Some(p) = precision {
                    while s.len() < p {
                        s.insert(0, '0');
                    }
                }
                while s.len() < width {
                    if left {
