// Minimal terminfo reader + parameterized string expander.
// Reproduces the behaviour of the `term` crate as observed from the original
// executable: terminal lookup, color capability handling and `reset()`.

use std::env;
use std::fs;
use std::path::PathBuf;

pub const SETAF: usize = 359;
pub const SETAB: usize = 360;
pub const SGR0: usize = 39;
pub const SGR: usize = 131;
/// index of the `colors` numeric capability
pub const COLORS: usize = 13;

pub struct TermInfo {
    pub numbers: Vec<i64>,
    pub strings: Vec<Option<Vec<u8>>>,
}

impl TermInfo {
    pub fn number(&self, idx: usize) -> Option<i64> {
        self.numbers.get(idx).copied()
    }
    pub fn string(&self, idx: usize) -> Option<&[u8]> {
        match self.strings.get(idx) {
            Some(Some(v)) => Some(v),
            _ => None,
        }
    }
    pub fn has_string(&self, idx: usize) -> bool {
        self.string(idx).is_some()
    }
    /// number of colors, following the `term` crate logic
    pub fn num_colors(&self) -> u32 {
        if self.has_string(SETAF) && self.has_string(SETAB) {
            match self.number(COLORS) {
                Some(n) => n as u32,
                None => 0,
            }
        } else {
            0
        }
    }
}

fn db_path_for_term(term: &str) -> Option<PathBuf> {
    let first_char = term.chars().next()?;
    let mut dirs_to_search: Vec<PathBuf> = Vec::new();
    if let Some(dir) = env::var_os("TERMINFO") {
        dirs_to_search.push(PathBuf::from(dir));
    }
    if let Ok(dirs) = env::var("TERMINFO_DIRS") {
        for i in dirs.split(':') {
            match i {
                "" => dirs_to_search.push(PathBuf::from("/usr/share/terminfo")),
                "false" => continue,
                i => dirs_to_search.push(PathBuf::from(i)),
            }
        }
    }
    if let Ok(home) = env::var("HOME") {
        dirs_to_search.push(PathBuf::from(home).join(".terminfo"));
    }
    dirs_to_search.push(PathBuf::from("/usr/share/terminfo"));
    dirs_to_search.push(PathBuf::from("/lib/terminfo"));
    dirs_to_search.push(PathBuf::from("/usr/share/lib/terminfo"));
    for mut p in dirs_to_search {
        if fs::metadata(&p).is_ok() {
            p = p.join(first_char.to_string()).join(term);
            if fs::metadata(&p).is_ok() {
                return Some(p);
            }
            p.set_file_name(format!("{:x}", term.as_bytes()[0]));
            if fs::metadata(&p).is_ok() {
                return Some(p);
            }
        }
    }
    None
}

