                            d.push(c2);
                        }
                        precision = d.parse::<usize>().ok();
                        break;
                    }
                    numstr.push(ch);
                }
                width = numstr.parse::<usize>().unwrap_or(0);
                let mut s = match last {
                    b'd' => {
                        let mut t = v.abs().to_string();
                        if v < 0 {
                            t.insert(0, '-');
                        } else if plus {
                            t.insert(0, '+');
                        } else if space {
                            t.insert(0, ' ');
                        }
                        if zeropad && !left {
                            let sign_len = if t.starts_with('-') || t.starts_with('+') { 1 } else { 0 };
                            while t.len() < width {
                                t.insert(sign_len, '0');
                            }
                        }
                        t
                    }
                    b'c' => ((v & 0xff) as u8 as char).to_string(),
                    b'x' => format!("{:x}", v),
                    b'X' => format!("{:X}", v),
                    b'o' => format!("{:o}", v),
                    _ => v.to_string(),
                };
                if let Some(p) = precision {
                    while s.len() < p {
                        s.insert(0, '0');
                    }
                }
                while s.len() < width {
                    if left {
                        s.push(' ');
                    } else {
                        s.insert(0, ' ');
                    }
                }
                out.extend_from_slice(s.as_bytes());
            }
            b'?' => {
                // %?cond%tthen%eelse%;
                let cond = pop!();
                // find matching %t ... %e ... %;  (no nesting support needed here)
                let mut j = i;
                let mut depth = 0i32;
                let mut then_start = None;
                let mut else_start = None;
                let mut end = n;
                while j < n {
                    if cap[j] == b'%' && j + 1 < n {
                        let c2 = cap[j + 1];
                        match c2 {
                            b'?' => depth += 1,
                            b';' => {
                                if depth == 0 {
                                    end = j;
                                    break;
                                } else {
                                    depth -= 1;
                                }
                            }
                            b't' if depth == 0 && then_start.is_none() => {
                                then_start = Some(j + 2);
                            }
                            b'e' if depth == 0 && then_start.is_some() && else_start.is_none() => {
                                else_start = Some(j + 2);
                            }
                            _ => {}
                        }
                        j += 2;
                    } else {
                        j += 1;
                    }
                }
                let ts = then_start.unwrap_or(i);
                let es = else_start.unwrap_or(end);
                let seg = if cond != 0 {
                    &cap[ts..es]
                } else {
                    &cap[es..end]
                };
                let sub = expand(seg, params);
                out.extend_from_slice(&sub);
                i = end + 1.min(n - end);
                if end >= n {
                    i = n;
                }
            }
            b't' | b'e' | b';' => {
                // stray, ignore
            }
            _ => {}
        }
    }
    out
}

