        numbers.push(v);
    }
    pos += num_count * numsize;
    let mut offsets = Vec::with_capacity(str_count);
    for i in 0..str_count {
        let off = pos + i * 2;
        if off + 2 > data.len() {
            return None;
        }
        offsets.push(i16::from_le_bytes([data[off], data[off + 1]]) as i64);
    }
    pos += str_count * 2;
    if pos + table_size > data.len() {
        return None;
    }
    let table = &data[pos..pos + table_size];
