    for off in offsets {
        if off < 0 || off as usize >= table.len() {
            strings.push(None);
            continue;
        }
        let start = off as usize;
        let end = table[start..]
            .iter()
            .position(|&b| b == 0)
            .map(|p| start + p)
            .unwrap_or(table.len());
        strings.push(Some(table[start..end].to_vec()));
    }
    Some(TermInfo { numbers, strings })
