/// terminfo parameterized string expansion (subset used by color capabilities)
pub fn expand(cap: &[u8], params: &[i64]) -> Vec<u8> {
    let mut params: Vec<i64> = params.to_vec();
    let mut out: Vec<u8> = Vec::with_capacity(cap.len() + 8);
    let mut stack: Vec<i64> = Vec::with_capacity(8);
    let mut dyn: [i64; 26] = [0i64; 26];
    let mut stc: [i64; 26] = [0i64; 26];
    let mut i = 0usize;
    let n = cap.len();
    macro_rules! pop {
        () => {
            stack.pop().unwrap_or(0)
        };
    }
    while i < n {
        let c = cap[i];
        if c != b'%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= n {
            break;
        }
        let k = cap[i];
        i += 1;
        match k {
            b'%' => out.push(b'%'),
            b'p' => {
                if i < n {
                    let p = cap[i];
                    i += 1;
                    let idx = (p as char).to_digit(10).unwrap_or(0) as usize;
                    let v = if idx == 0 {
                        params.first().copied().unwrap_or(0)
                    } else {
                        params.get(idx - 1).copied().unwrap_or(0)
                    };
                    stack.push(v);
                }
            }
            b'P' => {
                if i < n {
                    let v = pop!();
                    let name = cap[i] as char;
                    i += 1;
                    if name.is_ascii_lowercase() {
                        dyn[(name as u8 - b'a') as usize] = v;
                    } else if name.is_ascii_uppercase() {
                        stc[(name as u8 - b'A') as usize] = v;
                    }
                }
            }
            b'g' => {
                if i < n {
                    let name = cap[i] as char;
                    i += 1;
                    if name.is_ascii_lowercase() {
                        stack.push(dyn[(name as u8 - b'a') as usize]);
                    } else if name.is_ascii_uppercase() {
                        stack.push(stc[(name as u8 - b'A') as usize]);
                    }
                }
            }
            b'\'' => {
                if i < n {
                    stack.push(cap[i] as i64);
                    i += 1;
                    if i < n && cap[i] == b'\'' {
                        i += 1;
                    }
                }
            }
            b'{' => {
                let mut v: i64 = 0;
                let mut neg = false;
                if i < n && cap[i] == b'-' {
                    neg = true;
                    i += 1;
                }
                while i < n && cap[i].is_ascii_digit() {
                    v = v * 10 + (cap[i] - b'0') as i64;
                    i += 1;
                }
                if neg {
                    v = -v;
                }
                stack.push(v);
                if i < n && cap[i] == b'}' {
                    i += 1;
                }
            }
            b'l' => {
                let v = pop!();
                stack.push(v.to_string().len() as i64);
            }
            b'+' | b'-' | b'*' | b'/' | b'm' | b'&' | b'|' | b'^' | b'=' | b'<' | b'>' | b'A'
            | b'O' => {
                let y = pop!();
                let x = pop!();
                let r = match k {
                    b'+' => x + y,
                    b'-' => x - y,
                    b'*' => x * y,
                    b'/' => {
                        if y == 0 {
                            0
                        } else {
                            x / y
                        }
                    }
                    b'm' => {
                        if y == 0 {
                            0
                        } else {
                            x % y
                        }
                    }
                    b'&' => x & y,
                    b'|' => x | y,
                    b'^' => x ^ y,
                    b'=' => (x == y) as i64,
                    b'<' => (x < y) as i64,
                    b'>' => (x > y) as i64,
                    b'A' => (x != 0 && y != 0) as i64,
                    _ => (x != 0 || y != 0) as i64,
                };
                stack.push(r);
            }
            b'!' => {
                let v = pop!();
                stack.push((v == 0) as i64);
            }
            b'~' => {
                let v = pop!();
                stack.push(!v);
            }
            b'i' => {
                if let Some(a) = params.get_mut(0) {
                    *a += 1;
                }
                if let Some(a) = params.get_mut(1) {
                    *a += 1;
                }
            }
            b'c' => {
                let v = pop!();
                out.push((v & 0xff) as u8);
            }
            b'd' | b's' => {
                let v = pop!();
                out.extend_from_slice(v.to_string().as_bytes());
            }
            b'x' => {
                let v = pop!();
                out.extend_from_slice(format!("{:x}", v).as_bytes());
            }
            b'X' => {
                let v = pop!();
                out.extend_from_slice(format!("{:X}", v).as_bytes());
            }
            b'o' => {
                let v = pop!();
                out.extend_from_slice(format!("{:o}", v).as_bytes());
            }
            b':' | b'0'..=b'9' | b'#' | b' ' | b'+' | b'.' | b'-' => {
                // printf-like format: %[flags][width][.precision]<conv>
                let start = i - 1;
                let mut j = start;
                while j < n && !matches!(cap[j], b'd' | b'o' | b'x' | b'X' | b's' | b'c') {
                    j += 1;
                }
                if j >= n {
                    break;
                }
                let spec_str = String::from_utf8_lossy(&cap[start..j]).to_string();
                let last = cap[j];
                i = j + 1;
                let v = pop!();
                let body = &spec_str[1..];
                let mut flags = String::new();
                let mut it = body.chars().peekable();
                while let Some(ch) = it.peek() {
                    if matches!(ch, '-' | '0' | '+' | ' ' | '#' | ':') {
                        flags.push(*ch);
                        it.next();
                    } else {
                        break;
                    }
                }
                let mut numstr = String::new();
                for ch in it.by_ref() {
                    if ch == '.' {
                        continue;
                    }
                    numstr.push(ch);
                }
                let width = numstr.parse::<usize>().unwrap_or(0);
                let left = flags.contains('-');
                let zeropad = flags.contains('0');
                let mut s = match last {
                    b'd' => v.to_string(),
                    b'c' => ((v & 0xff) as u8 as char).to_string(),
                    b'x' => format!("{:x}", v),
                    b'X' => format!("{:X}", v),
                    b'o' => format!("{:o}", v),
                    _ => v.to_string(),
                };
                if zeropad && !left && s.len() < width {
                    let sign = s.starts_with('-');
                    let pad = width - s.len();
                    let zeros: String = "0".repeat(pad);
                    if sign {
                        s = format!("-{}{}", zeros, &s[1..]);
                    } else {
                        s = format!("{}{}", zeros, s);
                    }
                }
                while s.len() < width {
                    if left {
                        s.push(' ');
                    } else {
                        s.insert(0, ' ');
                    }
                }
                out.extend_from_slice(s.as_bytes());
            }
            b'?' => {
                // %?cond%t<then>%e<else>%;
                let cond = pop!();
                let mut j = i;
                let mut depth = 0i32;
                let mut then_start: Option<usize> = None;
                let mut else_start: Option<usize> = None;
                let mut end = n;
                while j < n {
                    if cap[j] == b'%' && j + 1 < n {
                        let c2 = cap[j + 1];
                        match c2 {
                            b'?' => depth += 1,
                            b';' => {
                                if depth == 0 {
                                    end = j;
                                    break;
                                } else {
                                    depth -= 1;
                                }
                            }
                            b't' if depth == 0 && then_start.is_none() => {
                                then_start = Some(j + 2);
                            }
                            b'e' if depth == 0 && then_start.is_some() && else_start.is_none() => {
                                else_start = Some(j + 2);
                            }
                            _ => {}
                        }
                        j += 2;
                    } else {
                        j += 1;
                    }
                }
                let ts = then_start.unwrap_or(i);
                let es = else_start.unwrap_or(end);
                let seg: &[u8] = if cond != 0 {
                    &cap[ts..es]
                } else {
                    &cap[es..end]
                };
                let sub = expand(seg, &params);
                out.extend_from_slice(&sub);
                if end >= n {
                    i = n;
                } else {
                    i = end + 2;
                }
            }
            b't' | b'e' | b';' => {}
            _ => {}
        }
    }
    out
}
