// Colored output built on top of the terminfo reader.  Mirrors the behaviour of
// the `term` crate as observed: bright colors are dimmed when the terminal does
// not support them and `fg()` fails (-> exit code 1) when there is no support.

use crate::terminfo::{self, TermInfo};
use std::io::{self, Write};

#[derive(Clone)]
pub struct TermColors {
    pub info: TermInfo,
    pub colors: u32,
}

impl TermColors {
    pub fn from_env() -> Option<TermColors> {
        let name = env::var("TERM").ok()?;
        let info = terminfo::from_name(&name)?;
        let colors = info.num_colors();
        Some(TermColors { info, colors })
    }
    fn dim_if_necessary(&self, color: u32) -> u32 {
        if color >= self.colors && color >= 8 && color < 16 {
            color - 8
        } else {
            color
        }
    }
}

pub struct Term<W: Write> {
    out: W,
    tc: TermColors,
    cur: Option<u32>,
}

// bright palette used by amber (dimmed automatically for 8 color terminals)
pub const GREEN: u32 = 10;
pub const CYAN: u32 = 14;
pub const YELLOW: u32 = 11;
pub const WHITE: u32 = 7;
pub const RED: u32 = 9;

impl<W: Write> Term<W> {
    pub fn new(out: W, tc: TermColors) -> Term<W> {
        Term {
            out,
            tc,
            cur: None,
        }
    }
    pub fn fg(&mut self, color: u32) -> io::Result<bool> {
        let color = self.tc.dim_if_necessary(color);
        if self.tc.colors > color {
            if self.cur == Some(color) {
                return Ok(true);
            }
            match self.tc.info.string(terminfo::SETAF) {
                Some(cap) => {
                    let s = terminfo::expand(cap, &[color as i64]);
                    self.out.write_all(&s)?;
                }
                None => return Ok(false),
            }
            self.cur = Some(color);
            Ok(true)
        } else {
            Ok(false)
        }
    }
    pub fn write(&mut self, data: &[u8]) -> io::Result<()> {
        self.out.write_all(data)
