                io::ErrorKind::NotFound,
                "no reset capability",
            ))
        }
    }
}

pub fn stdout_term() -> Option<Term<io::Stdout>> {
    let tc = TermColors::from_env()?;
    Some(Term::new(io::stdout(), tc))
}

pub fn stderr_term() -> Option<Term<io::Stderr>> {
    let tc = TermColors::from_env()?;
    Some(Term::new(io::stderr(), tc))
}
