// Command line parsing that mimics clap 2.x behaviour of the original binary.

use std::collections::BTreeMap;
use std::env;

#[derive(Clone, Copy, PartialEq)]
pub enum Kind {
    Flag,
    Opt,
}

pub struct ArgSpec {
    pub long: &'static str,
    pub short: Option<char>,
    pub help: Option<&'static str>,
    pub kind: Kind,
    pub value_name: &'static str,
    pub default: Option<&'static str>,
}

macro_rules! f {
    ($long:expr, $short:expr, $help:expr) => {
        ArgSpec {
            long: $long,
            short: $short,
            help: $help,
            kind: Kind::Flag,
            value_name: "",
            default: None,
        }
    };
}
macro_rules! o {
    ($long:expr, $value:expr, $default:expr, $help:expr) => {
        ArgSpec {
            long: $long,
            short: None,
            help: $help,
            kind: Kind::Opt,
            value_name: $value,
            default: Some($default),
        }
    };
}

pub fn specs() -> Vec<ArgSpec> {
    vec![
        f!("key-from-file", None, Some("Use file contents of KEYWORD as keyword for search")),
        f!("rep-from-file", None, Some("Use file contents of REPLACEMENT as keyword for replacement")),
        f!("verbose", None, Some("Verbose message")),
        f!("regex", Some('r'), Some("Enable regular expression search")),
        f!("no-regex", None, None),
        f!("column", None, Some("Enable column output")),
        f!("no-column", None, None),
        f!("row", None, Some("Enable row output")),
        f!("no-row", None, None),
        f!("binary", None, Some("Enable binary file search")),
        f!("no-binary", None, None),
        f!("statistics", None, Some("Enable statistics output")),
        f!("no-statistics", None, None),
        f!("skipped", None, Some("Enable skipped file output")),
        f!("no-skipped", None, None),
        f!("preserve-time", None, Some("Enable timestamp preserve")),
        f!("interactive", None, None),
        f!("no-interactive", None, Some("Disable interactive replace")),
        f!("recursive", None, None),
        f!("no-recursive", None, Some("Disable recursive directory search")),
        f!("symlink", None, None),
        f!("no-symlink", None, Some("Disable symbolic link follow")),
        f!("color", None, None),
        f!("no-color", None, Some("Disable colored output")),
        f!("file", None, None),
        f!("no-file", None, Some("Disable filename output")),
        f!("skip-vcs", None, None),
        f!("no-skip-vcs", None, Some("Disable vcs directory ( .hg/.git/.svn ) skip")),
        f!("skip-gitignore", None, None),
        f!("no-skip-gitignore", None, Some("Disable .gitignore skip")),
        f!("fixed-order", None, None),
        f!("no-fixed-order", None, Some("Disable output order guarantee")),
        f!("parent-ignore", None, None),
        f!("no-parent-ignore", None, Some("Disable .*ignore file search at parent directories")),
        f!("tbm", None, Some("[Experimental] Enable TBM matcher")),
        f!("sse", None, Some("[Experimental] Enable SSE 4.2")),
        f!("help", Some('h'), Some("Prints help information")),
        f!("version", Some('V'), Some("Prints version information")),
        o!("max-threads", "NUM", "20", Some("Number of max threads")),
        o!("size-per-thread", "BYTES", "1048576", Some("File size per one thread")),
        o!("bin-check-bytes", "BYTES", "256", Some("Read size for checking binary")),
        o!("mmap-bytes", "BYTES", "1048576", Some("[Experimental] Minimum size for using mmap")),
    ]
}

pub const VERSION_LINE: &str = "ambr 0.6.0";

pub fn bin_name(argv0: Option<&str>) -> String {
    match argv0 {
        Some(p) => {
            let p = p.replace('\\', "/");
            match p.rsplit('/').next() {
                Some(s) if !s.is_empty() => s.to_string(),
                _ => "ambr".to_string(),
            }
        }
        None => "ambr".to_string(),
    }
}

fn full_usage(bin: &str) -> String {
    format!("{} [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...", bin)
}

fn help_text(bin: &str) -> String {
    let mut s = String::new();
    s.push_str(&format!("{}\n\nUSAGE:\n    {}\n\n", VERSION_LINE, full_usage(bin)));
    s.push_str("FLAGS:\n");
    for a in specs().iter().filter(|a| a.help.is_some() && a.kind == Kind::Flag) {
        let mut left = String::new();
        match a.short {
            Some(c) => left.push_str(&format!("    -{}, ", c)),
            None => left.push_str("        "),
        }
        left.push_str(&format!("--{}", a.long));
        s.push_str(&format!("{}{:width$}{}\n", left, "", a.help.unwrap_or(""), width = 24 - left.len()));
    }
    s.push_str("\nOPTIONS:\n");
    for a in specs().iter().filter(|a| a.help.is_some() && a.kind == Kind::Opt) {
        let mut left = String::new();
        match a.short {
            Some(c) => left.push_str(&format!("    -{}, ", c)),
            None => left.push_str("        "),
        }
        left.push_str(&format!("--{} <{}>", a.long, a.value_name));
        s.push_str(&format!(
            "{}{:width$}{} [default: {}]\n",
            left,
            "",
            a.help.unwrap_or(""),
            a.default.unwrap_or(""),
            width = 29 - left.len()
        ));
    }
    s.push_str("\nARGS:\n");
    s.push_str("    <KEYWORD>        Keyword for search\n");
    s.push_str("    <REPLACEMENT>    Keyword for replace\n");
    s.push_str("    <PATHS>...       Search paths\n");
    s
}

// ---------------------------------------------------------------------------
// jaro-winkler used for the "Did you mean" suggestions (like strsim crate)
// ---------------------------------------------------------------------------
fn jaro(a: &str, b: &str) -> f64 {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let a_len = a_chars.len();
    let b_len = b_chars.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    }
    if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    if a_chars == b_chars {
        return 1.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_char) in a_chars.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, b_char) in b_chars.iter().enumerate() {
            if min_bound <= j && j <= max_bound && a_char == b_char && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a
        .chars()
        .zip(b.chars())
        .take_while(|(ac, bc)| ac == bc)
        .count()
        .min(4);
    let d = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if d <= 1.0 {
        d
    } else {
        1.0
    }
}

fn did_you_mean(v: &str, possible: &[&str]) -> Option<String> {
    let mut candidates: Vec<(f64, &str)> = possible
        .iter()
        .map(|pv| (jaro_winkler(v, pv), *pv))
        .filter(|(confidence, _)| *confidence > 0.8)
        .collect();
    candidates.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    candidates.reverse();
    candidates.first().map(|(_, pv)| pv.to_string())
}

// ---------------------------------------------------------------------------
// colorized error output (clap style)
// ---------------------------------------------------------------------------
fn stderr_is_tty() -> bool {
    unsafe { libc_isatty(2) }
}

extern "C" {
    fn isatty(fd: i32) -> i32;
}
#[allow(non_upper_case_globals)]
unsafe fn libc_isatty(fd: i32) -> bool {
    isatty(fd) == 1
}

fn term_dumb() -> bool {
    match env::var("TERM") {
        Ok(s) => s == "dumb",
        Err(_) => true,
    }
}

fn colored_error() -> bool {
    stderr_is_tty() && !term_dumb()
}

fn red(s: &str) -> String {
    if colored_error() {
        format!("\x1b[1;31m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}
fn yellow(s: &str) -> String {
    if colored_error() {
        format!("\x1b[33m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}
fn green(s: &str) -> String {
    if colored_error() {
        format!("\x1b[32m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}
/// clap's Format::Good is always colorized
fn always_green(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

pub struct ClapError {
    pub message: String,
}

impl ClapError {
    pub fn print(&self) {
        eprintln!("{}", self.message);
    }
}

pub struct Matches {
    pub counts: BTreeMap<&'static str, usize>,
    pub values: BTreeMap<&'static str, String>,
    pub keyword: Option<String>,
    pub replacement: Option<String>,
    pub paths: Vec<String>,
    used: Vec<&'static str>,
}

impl Matches {
    pub fn is_present(&self, name: &str) -> bool {
        self.counts.get(name).map(|c| *c > 0).unwrap_or(false)
    }
    pub fn value(&self, name: &str) -> Option<&String> {
        self.values.get(name)
    }
}

pub fn parse(argv: &[String]) -> Result<Matches, ClapError> {
    let bin = bin_name(argv.first().map(|s| s.as_str()));
    let specs = specs();
    let longs: Vec<&str> = specs.iter().map(|a| a.long).collect();
    let mut m = Matches {
        counts: BTreeMap::new(),
        values: BTreeMap::new(),
        keyword: None,
        replacement: None,
        paths: Vec::new(),
        used: Vec::new(),
    };
    let mut positionals: Vec<String> = Vec::new();
    let mut used_names: Vec<&'static str> = Vec::new();
    let mut record = |m: &mut Matches, spec: &ArgSpec, used_names: &mut Vec<&'static str>| {
        if !used_names.contains(&spec.long) {
            used_names.push(spec.long);
        }
        let _ = m;
    };
    let find_long = |name: &str| -> Option<&ArgSpec> { specs.iter().find(|a| a.long == name) };
    let find_short = |c: char| -> Option<&ArgSpec> { specs.iter().find(|a| a.short == Some(c)) };

    let mut i = 1usize;
    let mut after_dd = false;
    let mut pending_pos = 0usize; // how many positionals consumed (0,1,2+)
    while i < argv.len() {
        let a = argv[i].clone();
        if after_dd {
            positionals.push(a);
            i += 1;
            continue;
        }
        if a == "--" {
            after_dd = true;
            i += 1;
            continue;
        }
        if a.starts_with("--") {
            let body = &a[2..];
            let (name, inline) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            match find_long(name) {
                Some(spec) => {
                    if spec.long == "help" {
                        print!("{}", help_text(&bin));
                        std::process::exit(0);
                    }
                    if spec.long == "version" {
                        println!("{}", VERSION_LINE);
                        std::process::exit(0);
                    }
                    match spec.kind {
                        Kind::Flag => {
                            let c = m.counts.entry(spec.long).or_insert(0);
                            *c += 1;
                            record(&mut m, spec, &mut used_names);
                        }
                        Kind::Opt => {
                            let val = match inline {
                                Some(v) => Some(v),
                                None => {
                                    if i + 1 < argv.len() {
                                        let nxt = &argv[i + 1];
                                        if nxt.starts_with('-') && nxt.as_str() != "-" {
                                            None
                                        } else {
                                            i += 1;
                                            Some(argv[i].clone())
                                        }
                                    } else {
                                        None
                                    }
                                }
                            };
                            if let Some(v) = val {
                                // validate numeric options eagerly
                                if let Err(e) = parse_num(spec, &v) {
                                    return Err(e);
                                }
                                m.values.insert(spec.long, v);
                                record(&mut m, spec, &mut used_names);
                            }
                        }
                    }
                    i += 1;
                }
                None => {
                    let suggestion = did_you_mean(name, &longs);
                    let mut used: Vec<String> = Vec::new();
                    for n in used_names.iter() {
                        used.push(render_used(&specs, n));
                    }
                    if let Some(s) = &suggestion {
                        used.push(format!("--{}", s));
                    }
                    let msg = if used.is_empty() {
                        format!(
                            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n\n{}\n\nFor more information try {}",
                            red("error:"),
                            yellow(&a),
                            suggestion
                                .as_ref()
                                .map(|s| format!(
                                    "\n\tDid you mean {}{}?",
                                    always_green("--"),
                                    always_green(s)
                                ))
                                .unwrap_or_default(),
                            full_usage(&bin),
                            green("--help")
                        )
                    } else {
                        used.sort();
                        used.dedup();
                        format!(
                            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n\n{}\n\nFor more information try {}",
                            red("error:"),
                            yellow(&a),
                            suggestion
                                .as_ref()
                                .map(|s| format!(
                                    "\n\tDid you mean {}{}?",
                                    always_green("--"),
                                    always_green(s)
                                ))
                                .unwrap_or_default(),
                            smart_usage(&bin, &used),
                            green("--help")
                        )
                    };
                    return Err(ClapError { message: msg });
                }
            }
            continue;
        }
        if a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0usize;
            while ci < chars.len() {
                let c = chars[ci];
                match find_short(c) {
                    Some(spec) => {
                        if spec.long == "help" {
                            print!("{}", help_text(&bin));
                            std::process::exit(0);
                        }
                        if spec.long == "version" {
                            println!("{}", VERSION_LINE);
                            std::process::exit(0);
                        }
                        match spec.kind {
                            Kind::Flag => {
                                let cnt = m.counts.entry(spec.long).or_insert(0);
                                *cnt += 1;
                                record(&mut m, spec, &mut used_names);
                                ci += 1;
                            }
                            Kind::Opt => {
                                let rest: String = chars[ci + 1..].iter().collect();
                                let val = if !rest.is_empty() {
                                    let r = rest.trim_start_matches('=').to_string();
                                    if r.is_empty() {
                                        if i + 1 < argv.len() {
                                            i += 1;
                                            Some(argv[i].clone())
                                        } else {
                                            None
                                        }
                                    } else {
                                        Some(r)
                                    }
                                } else if i + 1 < argv.len() {
                                    let nxt = &argv[i + 1];
                                    if nxt.starts_with('-') && nxt.as_str() != "-" {
                                        None
                                    } else {
                                        i += 1;
                                        Some(argv[i].clone())
                                    }
                                } else {
                                    None
                                };
                                if let Some(v) = val {
                                    if let Err(e) = parse_num(spec, &v) {
                                        return Err(e);
                                    }
                                    m.values.insert(spec.long, v);
                                    record(&mut m, spec, &mut used_names);
                                }
                                ci = chars.len();
                            }
                        }
                    }
                    None => {
                        let mut used: Vec<String> = Vec::new();
                        for n in used_names.iter() {
                            used.push(render_used(&specs, n));
                        }
                        let msg = if used.is_empty() {
                            format!(
                                "{} Found argument '{}' which wasn't expected, or isn't valid in this context\n\n{}\n\nFor more information try {}",
                                red("error:"),
                                yellow(&a),
                                full_usage(&bin),
                                green("--help")
                            )
                        } else {
                            used.sort();
                            used.dedup();
                            format!(
                                "{} Found argument '{}' which wasn't expected, or isn't valid in this context\n\n{}\n\nFor more information try {}",
                                red("error:"),
                                yellow(&a),
                                smart_usage(&bin, &used),
                                green("--help")
                            )
                        };
                        return Err(ClapError { message: msg });
                    }
                }
            }
            i += 1;
            continue;
        }
        // positional
        positionals.push(a);
        i += 1;
    }
    let _ = &mut pending_pos;

    // apply defaults for options that were not supplied
    for spec in specs.iter() {
        if spec.kind == Kind::Opt && !m.values.contains_key(spec.long) {
            if let Some(d) = spec.default {
                m.values.insert(spec.long, d.to_string());
                record(&mut m, spec, &mut used_names);
            }
        }
    }

    // occurrence validation
    for spec in specs.iter() {
        if let Some(c) = m.counts.get(spec.long) {
            if *c > 1 {
                let disp = match spec.kind {
                    Kind::Flag => format!("--{}", spec.long),
                    Kind::Opt => format!("--{} <{}>", spec.long, spec.value_name),
                };
                let mut used: Vec<String> = Vec::new();
                for n in used_names.iter() {
                    used.push(render_used(&specs, n));
                }
                used.sort();
                used.dedup();
                let msg = format!(
                    "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}",
                    red("error:"),
                    yellow(&disp),
                    smart_usage(&bin, &used),
                    green("--help")
                );
                return Err(ClapError { message: msg });
            }
        }
    }

    // required positionals
    let missing: Vec<&str> = if positionals.is_empty() {
        vec!["<KEYWORD>", "<REPLACEMENT>"]
    } else if positionals.len() == 1 {
        vec!["<REPLACEMENT>"]
    } else {
        Vec::new()
    };
    if !missing.is_empty() {
        let mut used: Vec<String> = Vec::new();
        for n in used_names.iter() {
            used.push(render_used(&specs, n));
        }
        used.sort();
        used.dedup();
        let mut msg = format!(
            "{} The following required arguments were not provided:\n",
            red("error:")
        );
        for mm in missing.iter() {
            msg.push_str(&format!("    {}\n", mm));
        }
        msg.push_str(&format!("\n{}\n\nFor more information try {}", smart_usage(&bin, &used), green("--help")));
        return Err(ClapError { message: msg });
    }

    m.keyword = Some(positionals[0].clone());
    m.replacement = Some(positionals[1].clone());
    m.paths = positionals[2..].to_vec();
    Ok(m)
}

fn render_used(specs: &[ArgSpec], name: &str) -> String {
    match specs.iter().find(|a| a.long == name) {
        Some(spec) => match spec.kind {
            Kind::Flag => format!("--{}", spec.long),
            Kind::Opt => format!("--{} <{}>", spec.long, spec.value_name),
        },
        None => format!("--{}", name),
    }
}

fn smart_usage(bin: &str, used: &[String]) -> String {
    let mut s = format!("{} <KEYWORD> <REPLACEMENT>", bin);
    for u in used {
        s.push(' ');
        s.push_str(u);
    }
    s
}

fn parse_num(spec: &ArgSpec, v: &str) -> Result<(), ClapError> {
    if spec.kind == Kind::Opt {
        if let Err(e) = v.parse::<u64>() {
            let msg = format!(
                "{} Invalid value for '{}': {}\n",
                red("error:"),
                yellow(&format!("--{} <{}>", spec.long, spec.value_name)),
                e
            );
            return Err(ClapError { message: msg });
        }
    }
    Ok(())
}
