                }
            }
            start = end + 1;
            if start > n {
                break;
            }
            if line.is_empty() {
                continue;
            }
            if line[0] == b'#' {
                continue;
            }
            let mut negated = false;
            let mut pat = line;
            if pat[0] == b'!' {
                negated = true;
                pat = &pat[1..];
            }
            if pat.is_empty() {
                continue;
            }
            let mut dir_only = false;
            if pat.last() == Some(&b'/') {
                dir_only = true;
                pat = &pat[..pat.len() - 1];
            }
            if pat.is_empty() {
                continue;
            }
            let mut anchored = false;
            let mut p = pat;
            if p[0] == b'/' {
                anchored = true;
                p = &p[1..];
            }
            if !anchored {
                anchored = p.contains(&b'/');
            }
            if p.is_empty() {
                continue;
            }
            rules.push(Rule {
                negated,
                dir_only,
                anchored,
                pattern: p.to_vec(),
            });
        }
        IgnoreSet { rules }
    }

    /// returns true when the entry should be ignored
    pub fn is_ignored(&self, rel: &[u8], is_dir: bool) -> bool {
        let mut ignored = false;
        for r in self.rules.iter() {
            if r.dir_only && !is_dir {
                continue;
            }
            let target: Vec<u8> = if r.anchored {
                rel.to_vec()
            } else {
                // match against the file name part
