// glob matcher
// ---------------------------------------------------------------------------
pub fn glob_match(pat: &[u8], text: &[u8]) -> bool {
    m(pat, text)
}

fn m(p: &[u8], t: &[u8]) -> bool {
    let mut pi = 0usize;
    let mut ti = 0usize;
