                // brace alternation: find matching '}' and try each alternative
                let mut depth = 0;
                let mut j = pi;
                let mut alts: Vec<(usize, usize)> = Vec::new();
                let mut start = pi + 1;
                while j < p.len() {
                    if p[j] == b'{' {
                        depth += 1;
                    } else if p[j] == b'}' {
                        depth -= 1;
                        if depth == 0 {
                            alts.push((start, j));
                            break;
                        }
                    } else if p[j] == b',' && depth == 1 {
                        alts.push((start, j));
                        start = j + 1;
                    }
                    j += 1;
