                    alt.extend_from_slice(tail);
                    if m(&alt, rest_t) {
                        return true;
                    }
                }
                return false;
            }
            b'*' => {
                if pi + 1 < p.len() && p[pi + 1] == b'*' {
                    // "**"
                    let rest = &p[pi + 2..];
                    if rest.first() == Some(&b'/') {
                        let r2 = &rest[1..];
                        // match zero segments
                        if m(r2, &t[ti..]) {
                            return true;
                        }
                        // match one or more segments
                        let mut k = ti;
                        while k < t.len() {
                            if t[k] == b'/' {
                                if m(r2, &t[k + 1..]) {
                                    return true;
                                }
                            }
                            k += 1;
                        }
                        return false;
                    } else {
                        // ** matches zero or more chars (including /)
                        let mut k = ti;
                        loop {
                            if m(rest, &t[k..]) {
                                return true;
                            }
                            if k >= t.len() {
                                break;
                            }
                            k += 1;
                        }
                        return false;
                    }
                } else {
                    // single star: zero or more chars excluding '/'
                    let rest = &p[pi + 1..];
                    let mut k = ti;
                    loop {
                        if m(rest, &t[k..]) {
                            return true;
                        }
                        if k >= t.len() || t[k] == b'/' {
                            break;
                        }
                        k += 1;
                    }
                    return false;
                }
            }
            _ => {
                if ti >= t.len() || t[ti] != c {
                    return false;
                }
                ti += 1;
                pi += 1;
            }
        }
    }
}
