#[derive(Clone)]
pub struct Rule {
    pub negated: bool,
    pub dir_only: bool,
    pub anchored: bool,
    pub pattern: Vec<u8>,
}

#[derive(Clone, Default)]
pub struct IgnoreSet {
    pub rules: Vec<Rule>,
}

fn is_glob_special(c: u8) -> bool {
    matches!(c, b'*' | b'?' | b'[' | b']' | b'{' | b'}' | b',' | b'\\')
}

impl IgnoreSet {
    pub fn parse(data: &[u8]) -> IgnoreSet {
        let mut rules = Vec::new();
        let mut start = 0usize;
        let n = data.len();
        while start <= n {
            let end = match data[start..].iter().position(|&b| b == b'\n') {
                Some(p) => start + p,
                None => n,
            };
            let mut line = &data[start..end];
            if end >= n {
                // last line without newline
            }
            // strip trailing '\r'
            if line.last() == Some(&b'\r') {
                line = &line[..line.len() - 1];
            }
            // trim trailing whitespace
            while let Some(&c) = line.last() {
                if c == b' ' || c == b'\t' {
                    line = &line[..line.len() - 1];
                } else {
                    break;
                }
            }
            start = end + 1;
            if start > n {
                break;
            }
            if line.is_empty() {
                continue;
            }
            if line[0] == b'#' {
                continue;
            }
            let mut negated = false;
            let mut pat = line;
            if pat[0] == b'!' {
                negated = true;
                pat = &pat[1..];
            }
            if pat.is_empty() {
                continue;
            }
            let mut dir_only = false;
            if pat.last() == Some(&b'/') {
                dir_only = true;
                pat = &pat[..pat.len() - 1];
            }
            if pat.is_empty() {
                continue;
            }
            let mut anchored = false;
            let mut p = pat;
            if p[0] == b'/' {
                anchored = true;
                p = &p[1..];
            }
            if !anchored {
                anchored = p.contains(&b'/');
            }
            if p.is_empty() {
                continue;
            }
            rules.push(Rule {
                negated,
                dir_only,
                anchored,
                pattern: p.to_vec(),
            });
        }
        IgnoreSet { rules }
    }

    /// returns true when the entry should be ignored
    pub fn is_ignored(&self, rel: &[u8], is_dir: bool) -> bool {
        let mut ignored = false;
        for r in self.rules.iter() {
            if r.dir_only && !is_dir {
                continue;
            }
            let target: Vec<u8> = if r.anchored {
                rel.to_vec()
            } else {
                // match against the file name part
                match rel.iter().rposition(|&b| b == b'/') {
                    Some(p) => rel[p + 1..].to_vec(),
                    None => rel.to_vec(),
                }
            };
            if glob_match(&r.pattern, &target) {
                ignored = !r.negated;
            }
        }
        ignored
    }
}

// ---------------------------------------------------------------------------
// glob matcher
// ---------------------------------------------------------------------------
pub fn glob_match(pat: &[u8], text: &[u8]) -> bool {
    m(pat, text)
}

fn m(p: &[u8], t: &[u8]) -> bool {
    let mut pi = 0usize;
    let mut ti = 0usize;
    loop {
        if pi >= p.len() {
            return ti >= t.len();
        }
        let c = p[pi];
        match c {
            b'\\' => {
                if pi + 1 >= p.len() {
                    // trailing backslash: literal
                    if ti >= t.len() || t[ti] != b'\\' {
                        return false;
                    }
                    ti += 1;
                    pi += 1;
                    continue;
                }
                let e = p[pi + 1];
                if ti >= t.len() || t[ti] != e {
                    return false;
                }
                ti += 1;
                pi += 2;
            }
            b'?' => {
                if ti >= t.len() || t[ti] == b'/' {
                    return false;
                }
                ti += 1;
                pi += 1;
            }
            b'[' => {
                if ti >= t.len() {
                    return false;
                }
                let mut j = pi + 1;
                let mut neg = false;
                if j < p.len() && (p[j] == b'!' || p[j] == b'^') {
                    neg = true;
                    j += 1;
                }
                let mut first = true;
                let mut found = false;
                while j < p.len() {
                    if p[j] == b']' && !first {
                        break;
                    }
                    first = false;
                    if j + 2 < p.len() && p[j + 1] == b'-' && p[j + 2] != b']' {
                        let lo = p[j];
                        let hi = p[j + 2];
                        if t[ti] >= lo && t[ti] <= hi {
                            found = true;
                        }
                        j += 3;
                    } else {
                        if p[j] == t[ti] {
                            found = true;
                        }
                        j += 1;
                    }
                }
                if j >= p.len() {
                    // unterminated class: treat as literal
                    if t[ti] != b'[' {
                        return false;
                    }
                    ti += 1;
                    pi += 1;
                    continue;
                }
                if found == neg {
                    return false;
                }
                ti += 1;
                pi = j + 1;
            }
            b'{' => {
                // brace alternation: find matching '}' and try each alternative
                let mut depth = 0;
                let mut j = pi;
                let mut alts: Vec<(usize, usize)> = Vec::new();
                let mut start = pi + 1;
                while j < p.len() {
                    if p[j] == b'{' {
                        depth += 1;
                    } else if p[j] == b'}' {
                        depth -= 1;
                        if depth == 0 {
                            alts.push((start, j));
                            break;
                        }
                    } else if p[j] == b',' && depth == 1 {
                        alts.push((start, j));
                        start = j + 1;
                    }
                    j += 1;
                }
                if j >= p.len() {
                    // unterminated: literal '{'
                    if ti >= t.len() || t[ti] != b'{' {
                        return false;
                    }
                    ti += 1;
                    pi += 1;
                    continue;
                }
                let tail = &p[j + 1..];
                let rest_t = &t[ti..];
                for (a, b) in alts.iter() {
                    let mut alt: Vec<u8> = p[a..*b].to_vec();
                    alt.extend_from_slice(tail);
                    if m(&alt, rest_t) {
                        return true;
                    }
                }
                return false;
            }
            b'*' => {
                if pi + 1 < p.len() && p[pi + 1] == b'*' {
                    // "**"
                    let rest = &p[pi + 2..];
                    if rest.first() == Some(&b'/') {
                        let r2 = &rest[1..];
                        // match zero segments
                        if m(r2, &t[ti..]) {
                            return true;
                        }
                        // match one or more segments
                        let mut k = ti;
                        while k < t.len() {
                            if t[k] == b'/' {
                                if m(r2, &t[k + 1..]) {
                                    return true;
                                }
                            }
                            k += 1;
                        }
                        return false;
                    } else {
                        // ** matches zero or more chars (including /)
                        let mut k = ti;
                        loop {
                            if m(rest, &t[k..]) {
                                return true;
                            }
                            if k >= t.len() {
                                break;
                            }
                            k += 1;
                        }
                        return false;
                    }
                } else {
                    // single star: zero or more chars excluding '/'
                    let rest = &p[pi + 1..];
                    let mut k = ti;
                    loop {
                        if m(rest, &t[k..]) {
                            return true;
                        }
                        if k >= t.len() || t[k] == b'/' {
                            break;
                        }
                        k += 1;
                    }
                    return false;
                }
            }
            _ => {
                if ti >= t.len() || t[ti] != c {
                    return false;
                }
                ti += 1;
                pi += 1;
            }
        }
    }
