// Directory walking with skip detection, matching the observed behaviour.

use crate::gitignore::IgnoreSet;
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};

pub struct WalkOutput {
    pub files: Vec<PathBuf>,
    pub skips: Vec<String>,
    pub found_parent_ignore: Vec<String>,
    pub errors: Vec<String>,
}

const VCS: [&str; 4] = [".git", ".hg", ".svn", ".bzr"];

pub struct WalkCfg {
    pub recursive: bool,
    pub symlink: bool,
    pub skip_vcs: bool,
    pub skip_gitignore: bool,
    pub parent_ignore: bool,
}

/// Find the closest ancestor directory (starting at `start` and walking up)
/// that contains a .gitignore. Returns (dir containing it, path expression)
fn find_parent_gitignore(start: &Path) -> Option<(PathBuf, String)> {
    let mut expr = String::new();
    let mut cur: PathBuf = start.to_path_buf();
    // first element: the start path itself, then go up using "/.."
    expr.push_str(&cur.to_string_lossy().to_string());
    let mut first = true;
    loop {
        // consider parent of current
        let parent_expr = if first {
            format!("{}/..", expr)
        } else {
            format!("{}/..", expr)
        };
        let parent_path: PathBuf = {
            let s = expr.clone();
            let mut p = PathBuf::from(&s);
            p.push("..");
            p
        };
        if !parent_path.exists() {
            return None;
        }
        let gi = parent_path.join(".gitignore");
        if gi.is_file() {
            return Some((parent_path.clone(), parent_expr));
        }
        // move up one level in the expression
        expr = parent_expr;
        first = false;
        // stop when we reach the filesystem root (expr ends with "/..")
        let norm = normalize_dots(&expr);
        if norm == "/" || norm.is_empty() {
            return None;
        }
        if expr.matches("/..").count() > 64 {
            return None;
        }
    }
}

fn normalize_dots(p: &str) -> String {
    let parts: Vec<&str> = p.split('/').filter(|s| !s.is_empty()).collect();
    let mut stack: Vec<&str> = Vec::new();
    for s in parts {
        if s == ".." {
            if !stack.is_empty() {
                stack.pop();
            }
        } else if s == "." {
            continue;
        } else {
            stack.push(s);
        }
    }
    let mut r = String::new();
    for s in stack {
        r.push('/');
        r.push_str(s);
    }
    if r.is_empty() {
        r.push('/');
    }
    r
}

pub fn walk(
    paths: &[String],
    cfg: &WalkCfg,
    seen: &mut HashSet<PathBuf>,
    skips: &mut Vec<String>,
    found_parent: &mut Vec<String>,
    errors: &mut Vec<String>,
) -> Vec<PathBuf> {
    let mut files: Vec<PathBuf> = Vec::new();
    for p in paths {
        let path = PathBuf::from(p);
        // parent ignore handling
        let mut base_ignore: Option<IgnoreSet> = None;
        if cfg.parent_ignore {
            if let Some((dir, expr)) = find_parent_gitignore(&path) {
                found_parent.push(format!(
                    "Found .gitignore at the parent directory: {:?}",
                    expr
                ));
                if let Ok(data) = fs::read(dir.join(".gitignore")) {
                    base_ignore = Some(IgnoreSet::parse(&data));
                }
            }
        }
        match fs::metadata(&path) {
            Err(e) => {
                errors.push(format!("{} @ {}", e, path.display()));
                continue;
            }
            Ok(md) => {
                if md.is_file() {
                    // direct file: no gitignore check
                    if let Some(can) = fs::canonicalize(&path).ok() {
                        if seen.contains(&can) {
                            continue;
                        }
                        seen.insert(can);
                    }
                    files.push(path);
                } else if md.is_dir() {
                    walk_dir(
                        &path,
                        &path,
                        base_ignore,
                        cfg,
                        seen,
                        &mut files,
                        skips,
                    );
                } else {
                    // other (fifo, etc.)
                }
            }
        }
    }
    files
}

fn is_vcs(name: &str) -> bool {
    VCS.contains(&name)
}

fn walk_dir(
    display_base: &Path,
    dir: &Path,
    ignore: Option<IgnoreSet>,
    cfg: &WalkCfg,
    seen: &mut HashSet<PathBuf>,
    files: &mut Vec<PathBuf>,
    skips: &mut Vec<String>,
) {
    // dedup by canonical path
    let canon = match fs::canonicalize(dir) {
        Ok(c) => c,
        Err(_) => return,
    };
    if seen.contains(&canon) {
        return;
    }
    seen.insert(canon);

    // load local .gitignore (replaces parent's)
    let mut cur_ignore = ignore;
    let local_gi = dir.join(".gitignore");
    if cfg.skip_gitignore {
        if let Ok(data) = fs::read(&local_gi) {
            cur_ignore = Some(IgnoreSet::parse(&data));
        }
    }
    let rd = match fs::read_dir(dir) {
        Ok(r) => r,
        Err(_) => return,
    };
    let mut entries: Vec<(PathBuf, String, bool)> = Vec::new();
    for e in rd.flatten() {
        let name = e.file_name().to_string_lossy().to_string();
        let path = e.path();
        let is_dir = match fs::metadata(&path) {
            Ok(m) => m.is_dir(),
            Err(_) => match fs::symlink_metadata(&path) {
                Ok(m) => m.is_dir(),
                Err(_) => false,
            },
        };
        entries.push((path, name, is_dir));
    }
    let ignore = cur_ignore;
    for (path, name, is_dir) in entries {
        // vcs skip
        if cfg.skip_vcs && is_dir && is_vcs(&name) {
            skips.push(format!("Skip (vcs file)  : {:?}", display_base.join(&name)));
            continue;
        }
        if let Some(iset) = &ignore {
            if cfg.skip_gitignore {
                let rel = relative_to(&display_base.join(&name), display_base);
                if iset.is_ignored(rel.as_bytes(), is_dir) {
                    skips.push(format!(
                        "Skip (.gitignore): {:?}",
                        display_base.join(&name)
                    ));
                    continue;
                }
            }
        }
        if is_dir {
            if !cfg.recursive {
                continue;
            }
            // follow symlinked directories
            let follow = match fs::symlink_metadata(&path) {
                Ok(m) => if m.file_type().is_symlink() { cfg.symlink } else { true },
                Err(_) => false,
            };
            if !follow {
                continue;
            }
            walk_dir(&display_base.join(&name), &path, ignore.clone(), cfg, seen, files, skips);
        } else {
            // file or symlink to file
            let is_symlink = match fs::symlink_metadata(&path) {
                Ok(m) => m.file_type().is_symlink(),
                Err(_) => false,
            };
            if is_symlink && !cfg.symlink {
                continue;
            }
            if let Some(can) = fs::canonicalize(&path).ok() {
                if seen.contains(&can) {
                    continue;
                }
                seen.insert(can);
            }
            files.push(display_base.join(&name));
        }
    }
}

fn relative_to(path: &Path, base: &Path) -> String {
    match path.strip_prefix(base) {
        Ok(r) => r.to_string_lossy().to_string(),
        Err(_) => path.to_string_lossy().to_string(),
    }
}
