// Searching: finds matches inside files, computes row/column values that
// reproduce the (quirky) values printed by the original tool.

use regex::bytes::Regex;

pub struct Matcher {
    pub regex: Option<Regex>,
    pub keyword: Vec<u8>,
}

pub struct Found {
    pub start: usize,
    pub end: usize,
    pub line_start: usize,
    pub line_end: usize,
    pub line_no: usize,
    pub col: usize,
    pub row: usize,
    pub matched: Vec<u8>,
    pub replacement: Vec<u8>,
}

impl Matcher {
    pub fn new(keyword: &[u8], replacement: &[u8], regex: Option<Regex>) -> Matcher {
        Matcher {
            regex,
            keyword: keyword.to_vec(),
            _dummy: (),
        }
    }

    pub fn find_all(&self, data: &[u8], line_offset: usize) -> Vec<Found> {
        let mut out = Vec::new();
        let mut from = 0usize;
        let mut prev_line_no: i64 = -1;
        loop {
            let (s, e, mtext, repl) = match self.find_next(data, from) {
                Some(v) => v,
                None => break,
            };
            // compute line info
            let line_start = match memchr::memrchr(b'\n', &data[..s]) {
                Some(p) => p + 1,
                None => 0,
            };
            let line_end = match memchr::memchr(b'\n', &data[e..]) {
                Some(p) => e + p,
                None => data.len(),
            };
            // number of newlines in data[..s]
            let nl = memchr::memchr_iter(b'\n', &data[..s]).count();
            let line_no = nl + 1 + line_offset;
            let col = s - line_start;
            let row = col + if line_no > 1 { 1 } else { 0 };
            out.push(Found {
                start: s,
                end: e,
                line_start,
                line_end,
                line_no,
                col,
                row,
                matched: mtext,
                replacement: repl,
            });
            if e == from {
                break;
            }
            from = e;
            let _ = prev_line_no;
            prev_line_no = line_no as i64;
        }
        out
    }

    fn find_next(&self, data: &[u8], from: usize) -> Option<(usize, usize, Vec<u8>, Vec<u8>)> {
        if from > data.len() {
            return None;
        }
        match &self.regex {
            Some(re) => {
                if let Some(m) = re.find_at(data, from) {
                    let text = m.as_bytes().to_vec();
                    Some((m.start(), m.end(), text, self.replacement.clone()))
                } else {
                    None
                }
            }
