use regex::bytes::Regex;
fn main(){
    let cases: Vec<(&str,&str)> = vec![
        ("(aaa) (?<pat>bbb)", "$1 $pat ${1} ${pat}"),
        ("a", "<$1>"), ("a", "$x"), ("a", "$"), ("a", "a$"), ("a", "$$"),
        ("a", "$0$0"), ("(a)", "$10"), ("(a)", "${10}"), ("a", "\\$1"), ("a", "\\n"),
        ("a", "%%"), ("(?<pat>a)", "$p"), ("(?<pat>a)", "${pat}"), ("(a)(a)", "$2$1"),
        ("a", "$1a"), ("a", "${1a}"), ("a", "$_"), ("a", "$-1"), ("a", "${-1}"),
        ("a", "$1$"), ("a", "a$$b"), ("a", "${}${}"), ("a", "$name$1"),
    ];
    for (pat, rep) in cases {
        let re = match Regex::new(pat) { Ok(r) => r, Err(e) => { println!("{:?} COMPILE ERR {}", pat, e); continue } };
        let data = b"aaa bbb";
        let out = re.replace_all(data, rep.as_bytes());
        println!("{:?} {:?} -> {:?}", pat, rep, String::from_utf8_lossy(&out));
    }
}
