{"command": "cat > src/search.rs <<'RSEOF'
// Searching: finds matches inside files and computes the row/column values
// printed by the original tool (including its quirks).

use regex::bytes::{Captures, Regex};

pub struct Matcher {
    pub regex: Option<Regex>,
    pub keyword: Vec<u8>,
}

pub struct Found {
    pub start: usize,
    pub end: usize,
    pub line_start: usize,
    pub line_end: usize,
    pub line_no: usize,
    pub col: usize,
    pub row: usize,
    pub matched: Vec<u8>,
    pub replacement: Vec<u8>,
}

const LF: u8 = b'\n';
const TAB: u8 = b'\t';
const CR: u8 = b'\r';

/// unescape + $-expansion of the replacement text
pub fn expand_replacement(rep: &[u8], caps: Option<&Captures>) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::with_capacity(rep.len());
    let mut i = 0usize;
    let n = rep.len();
    while i < n {
        let c = rep[i];
        if c == b'\\' {
            if i + 1 < n {
                let nx = rep[i + 1];
                match nx {
                    b'n' => {
                        out.push(LF);
                        i += 2;
                    }
                    b't' => {
                        out.push(TAB);
                        i += 2;
                    }
                    b'r' => {
                        out.push(CR);
                        i += 2;
                    }
                    b'\\' => {
                        out.push(b'\\');
                        i += 2;
                        // the character following an escaped backslash is itself
                        // escaped
                        if i < n {
                            let c2 = rep[i];
                            match c2 {
                                b'n' => {
                                    out.push(LF);
                                    i += 1;
                                }
                                b't' => {
                                    out.push(TAB);
                                    i += 1;
                                }
                                b'r' => {
                                    out.push(CR);
                                    i += 1;
                                }
                                _ => {}
                            }
                        }
                    }
                    _ => {
                        out.push(b'\\');
                        out.push(nx);
                        i += 2;
                    }
                }
            } else {
                out.push(b'\\');
                i += 1;
            }
            continue;
        }
        if c == b'$' {
            if let Some(cs) = caps {
                i = expand_dollar(rep, i, cs, &mut out);
                continue;
            }
        }
        out.push(c);
        i += 1;
    }
    out
}

fn expand_dollar(rep: &[u8], mut i: usize, caps: &Captures, out: &mut Vec<u8>) -> usize {
    let n = rep.len();
    // i points at '$'
    i += 1;
    if i >= n {
        out.push(b'$');
        return i;
    }
    let c = rep[i];
    if c == b'$' {
        out.push(b'$');
        return i + 1;
    }
    if c == b'{' {
        // ${name}
        let start = i + 1;
        let mut j = start;
        while j < n && rep[j] != b'}' {
            j += 1;
        }
        if j >= n {
            out.push(b'$');
            return i;
        }
        let name = &rep[start..j];
        push_group(caps, name, out);
        return j + 1;
    }
    // bare name: [a-zA-Z0-9_]+
    if !is_name_char(c) {
        out.push(b'$');
        return i;
    }
    let start = i;
    let mut j = i;
    while j < n && is_name_char(rep[j]) {
        j += 1;
    }
    let name = &rep[start..j];
    push_group(caps, name, out);
    j
}

fn is_name_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_'
}

fn push_group(caps: &Captures, name: &[u8], out: &mut Vec<u8>) {
    let s = String::from_utf8_lossy(name).to_string();
    if let Some(g) = caps.name(&s) {
        out.extend_from_slice(g.as_bytes());
    } else if let Ok(idx) = s.parse::<usize>() {
        if let Some(g) = caps.get(idx) {
            out.extend_from_slice(g.as_bytes());
        }
    }
}

impl Matcher {
    pub fn new(keyword: &[u8], replacement: &[u8], regex: Option<Regex>) -> Matcher {
        Matcher {
            regex,
            keyword: keyword.to_vec(),
        }
    }

    pub fn find_all(&self, data: &[u8], line_offset: usize, replacement: &[u8]) -> Vec<Found> {
        let mut out = Vec::new();
        let mut from = 0usize;
        loop {
            let (s, e, mtext, repl) = match self.find_next(data, from, replacement) {
                Some(v) => v,
                None => break,
            };
            let line_start = match memchr::memrchr(b'\n', &data[..s]) {
                Some(p) => p + 1,
                None => 0,
            };
            let line_end = match memchr::memchr(b'\n', &data[e..]) {
                Some(p) => e + p,
                None => data.len(),
            };
            let nl = memchr::memchr_iter(b'\n', &data[..s]).count();
            let line_no = nl + 1 + line_offset;
            let col = s - line_start;
            let row = col + if line_no > 1 { 1 } else { 0 };
            out.push(Found {
                start: s,
                end: e,
                line_start,
                line_end,
                line_no,
                col,
                row,
                matched: mtext,
                replacement: repl,
            });
            if e <= from {
                break;
            }
            from = e;
        }
        out
    }

    fn find_next(
        &self,
        data: &[u8],
        from: usize,
        replacement: &[u8],
    ) -> Option<(usize, usize, Vec<u8>, Vec<u8>)> {
        if from > data.len() {
            return None;
        }
        match &self.regex {
            Some(re) => {
                if let Some(m) = re.find_at(data, from) {
                    let text = m.as_bytes().to_vec();
                    // compute capture expansion
                    if let Some(cs) = re.captures_from_pos(data, m.start()) {
                        let rep = expand_replacement(replacement, Some(&cs));
                        Some((m.start(), m.end(), text, rep))
                    } else {
                        Some((
                            m.start(),
                            m.end(),
                            text,
                            expand_replacement(replacement, None),
                        ))
                    }
                } else {
                    None
                }
            }
            None => {
                if self.keyword.is_empty() {
                    // matches at every position: emulate the original hang by
                    // returning a match at every byte (caller loops forever)
                    return Some((
                        from,
                        from + 1,
                        Vec::new(),
                        replacement.to_vec(),
                    ));
                }
                let s = memmem(&data[from..], &self.keyword)?;
                let st = s + from;
                Some((
                    st,
                    st + self.keyword.len(),
                    self.keyword.clone(),
                    replacement.to_vec(),
                ))
            }
        }
    }
}

/// simple two-way / memmem search
pub fn memmem(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
    if hay.len() < needle.len() {
        return None;
    }
    if needle.len() == 1 {
        return memchr::memchr(needle[0], hay);
    }
    let last = needle[needle.len() - 1];
    let mut skip: [usize; 256] = [needle.len(); 256];
    for (i, &c) in needle.iter().enumerate() {
        skip[c as usize] = needle.len() - i - 1;
    }
    if skip[last as usize] == 0 {
        skip[last as usize] = 1;
    }
    let mut pos = 0usize;
    while pos + needle.len() <= hay.len() {
        let end = pos + needle.len() - 1;
        if hay[end] == last {
            if &hay[pos..pos + needle.len()] == needle {
                return Some(pos);
            }
        }
        pos += skip[hay[end] as usize];
    }
    None
}
RSEOF
echo ok"}

