        let mut out = Vec::new();
        let mut from = 0usize;
        loop {
            let (s, e, mtext, repl) = match self.find_next(data, from, replacement) {
                Some(v) => v,
                None => break,
            };
            let line_start = match memchr::memrchr(b'\n', &data[..s]) {
                Some(p) => p + 1,
                None => 0,
            };
            let line_end = match memchr::memchr(b'\n', &data[e..]) {
                Some(p) => e + p,
