                let st = s + from;
                Some((
                    st,
                    st + self.keyword.len(),
                    self.keyword.clone(),
                    replacement.to_vec(),
                ))
            }
        }
    }
}

/// simple two-way / memmem search
pub fn memmem(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
    if hay.len() < needle.len() {
        return None;
    }
    if needle.len() == 1 {
        return memchr::memchr(needle[0], hay);
    }
    let last = needle[needle.len() - 1];
    let mut skip: [usize; 256] = [needle.len(); 256];
    for (i, &c) in needle.iter().enumerate() {
        skip[c as usize] = needle.len() - i - 1;
    }
    if skip[last as usize] == 0 {
        skip[last as usize] = 1;
    }
    let mut pos = 0usize;
    while pos + needle.len() <= hay.len() {
        let end = pos + needle.len() - 1;
        if hay[end] == last {
            if &hay[pos..pos + needle.len()] == needle {
                return Some(pos);
            }
        }
        pos += skip[hay[end] as usize];
    }
    None
}
