// Match display + interactive prompt, byte compatible with the original tool.

use crate::args::Matches;
use crate::color::{Term, CYAN, GREEN, WHITE, YELLOW};
use std::io::Write;

pub struct Cfg {
    pub color: bool,
    pub file: bool,
    pub column: bool,
    pub row: bool,
    pub interactive: bool,
}

pub struct Printer<W: Write> {
    pub term: Term<W>,
    pub cfg: Cfg,
}

impl<W: Write> Printer<W> {
    pub fn line_prefix(&self, file: &str, line_no: usize, row: usize) -> (String, usize) {
        let mut p = String::new();
        if self.cfg.file {
            p.push_str(file);
            p.push_str(": ");
        }
        if self.cfg.column {
            p.push_str(&format!("{}:", line_no));
        }
        if self.cfg.row {
            p.push_str(&format!("{}:", row));
        }
        if p.len() < 4 {
            while p.len() < 4 {
                p.push(' ');
            }
        }
        (p.clone(), p.len())
    }

    pub fn write_highlight(
        &mut self,
        prefix_text: &[u8],
        hl: &[u8],
        suffix_text: &[u8],
    ) -> std::io::Result<()> {
        if self.cfg.color {
            if !prefix_text.is_empty() {
                self.term.fg(WHITE)?;
                self.term.write(prefix_text)?;
            }
            self.term.fg(YELLOW)?;
            self.term.write(hl)?;
            self.term.fg(WHITE)?;
            self.term.write(suffix_text)?;
        } else {
            self.term.write(prefix_text)?;
            self.term.write(hl)?;
            self.term.write(suffix_text)?;
        }
        Ok(())
    }

    pub fn print_match(
        &mut self,
        file: &str,
        line_no: usize,
        row: usize,
        line: &[u8],
        hl_start: usize,
        hl_text: &[u8],
        newline: &[u8],
        nl_hl_start: usize,
        nl_hl_text: &[u8],
    ) -> std::io::Result<()> {
        let (prefix, plen) = self.line_prefix(file, line_no, row);
        let arrow: String = {
            let mut s = String::new();
            for _ in 0..(plen.saturating_sub(3)) {
                s.push(' ');
            }
            s.push_str("-> ");
            s
        };
        if self.cfg.color {
            self.term.fg(GREEN)?;
            self.term.write(file.as_bytes())?;
            self.term.fg(CYAN)?;
            self.term.write(": ")?;
            self.term.fg(CYAN)?;
            self.term.write(&prefix_after_file(&prefix, file).as_bytes())?;
        } else {
            self.term.write(prefix.as_bytes())?;
        }
        let ls = &line[..hl_start.min(line.len())];
        let mid = &line[hl_start.min(line.len())..(hl_start + hl_text.len()).min(line.len())];
        let se = &line[(hl_start + hl_text.len()).min(line.len())..];
        self.write_highlight(ls, mid, se)?;
        self.term.write(b"\n")?;
        if self.cfg.color {
            self.term.fg(CYAN)?;
        }
        self.term.write(arrow.as_bytes())?;
        let ls2 = &newline[..nl_hl_start.min(newline.len())];
        let mid2 = &newline
            [nl_hl_start.min(newline.len())..(nl_hl_start + nl_hl_text.len()).min(newline.len())];
        let se2 = &newline[(nl_hl_start + nl_hl_text.len()).min(newline.len())..];
        self.write_highlight(ls2, mid2, se2)?;
        self.term.write(b"\n")?;
        Ok(())
    }

    pub fn print_prompt(&mut self) -> std::io::Result<()> {
        if self.cfg.color {
            self.term.fg(CYAN)?;
        }
        self.term
            .write(b"Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: ")
    }
}

fn prefix_after_file(prefix: &str, file: &str) -> String {
    // prefix = file + ": " + numbers (+padding); we already wrote file and ": "
    let skip = file.len() + 2;
    if skip >= prefix.len() {
        String::new()
    } else {
        prefix[skip..].to_string()
    }
}

pub enum Answer {
    Yes,
    No,
    All,
    Quit,
    Again,
    Eof,
}

pub fn read_answer() -> Answer {
    use std::io::Read;
    let mut buf = [0u8; 1];
    loop {
        let r = std::io::stdin().read(&mut buf);
        match r {
            Ok(0) => return Answer::Eof,
            Ok(_) => {
                let c = buf[0];
                print!("{}", c as char);
                if c != b'\n' {
                    println!();
                }
                let _ = std::io::stdout().flush();
                return match c {
                    b'y' | b'Y' | b' ' | b'\r' | b'\n' => Answer::Yes,
                    b'n' | b'N' => Answer::No,
                    b'a' | b'A' => Answer::All,
                    b'q' | b'Q' => Answer::Quit,
                    _ => Answer::Again,
                };
            }
            Err(_) => return Answer::Eof,
        }
    }
}
