        }
        Ok(())
    }

    pub fn print_match(
        &mut self,
        file: &str,
        line_no: usize,
        row: usize,
        line: &[u8],
        hl_start: usize,
        hl_text: &[u8],
        newline: &[u8],
        nl_hl_start: usize,
        nl_hl_text: &[u8],
    ) -> std::io::Result<()> {
        let prefix = line_prefix(&self.cfg, file, line_no, row);
        let plen = prefix.len();
        let mut arrow = String::new();
        for _ in 0..plen.saturating_sub(3) {
            arrow.push(' ');
        }
        arrow.push_str("-> ");
        if self.cfg.color {
            self.term.fg(GREEN)?;
            self.term.write(file.as_bytes())?;
            self.term.fg(CYAN)?;
            let skip = file.len() + 2;
            let rest: &str = if skip >= prefix.len() { "" } else { &prefix[skip..] };
            self.term.write(rest.as_bytes())?;
        } else {
            self.term.write(prefix.as_bytes())?;
        }
        let s1 = hl_start.min(line.len());
        let e1 = (hl_start + hl_text.len()).min(line.len());
        self.write_highlight(&line[..s1], hl_text, &line[e1..])?;
        self.term.write(b"\n")?;
        if self.cfg.color {
            self.term.fg(CYAN)?;
        }
        self.term.write(arrow.as_bytes())?;
        let s2 = nl_hl_start.min(newline.len());
        let e2 = (nl_hl_start + nl_hl_text.len()).min(newline.len());
        self.write_highlight(&newline[..s2], nl_hl_text, &newline[e2..])?;
        self.term.write(b"\n")?;
        Ok(())
    }

