        let mut buf = [0u8; 4];
        let ch = c as char;
        let s = ch.to_string();
        let b = s.as_bytes();
        let l = b.len().min(4);
        buf[..l].copy_from_slice(&b[..l]);
        self.term.write(&buf[..l])?;
        if c != b'\n' {
            self.term.write(b"\n")?;
        }
        Ok(())
    }
