/// On EOF it blocks forever (matching the observed behaviour).
pub fn read_answer<W: Write>(p: &mut Printer<W>) -> Answer {
    use std::io::Read;
    let mut buf = [0u8; 1];
    loop {
        let r = std::io::stdin().read(&mut buf);
