                let _ = p.echo(c);
                return match c {
                    b'y' | b'Y' | b' ' | b'\r' | b'\n' => Answer::Yes,
                    b'n' | b'N' => Answer::No,
                    b'a' | b'A' => Answer::All,
                    b'q' | b'Q' => Answer::Quit,
