        let r = std::io::stdin().read(&mut buf);
        match r {
            Ok(0) => {
                // block forever like the original
                loop {
                    std::thread::sleep(std::time::Duration::from_secs(3600));
                }
            }
            Ok(_) => {
                let c = buf[0];
                let _ = p.echo(c);
                return match c {
                    b'y' | b'Y' | b' ' | b'\r' | b'\n' => Answer::Yes,
                    b'n' | b'N' => Answer::No,
                    b'a' | b'A' => Answer::All,
                    b'q' | b'Q' => Answer::Quit,
                    _ => Answer::Again,
                };
            }
            Err(_) => {
                loop {
                    std::thread::sleep(std::time::Duration::from_secs(3600));
                }
            }
        }
    }
}
