// Terminal raw-mode handling for the interactive prompt.

use std::os::unix::io::AsRawFd;

#[repr(C)]
#[derive(Clone, Copy)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

extern "C" {
    fn tcgetattr(fd: i32, termios_p: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios_p: *const Termios) -> i32;
    fn isatty(fd: i32) -> i32;
}

pub fn stdin_is_tty() -> bool {
    unsafe { isatty(0) == 1 }
}

pub struct RawGuard {
    saved: Termios,
}

impl RawGuard {
    pub fn new() -> Option<RawGuard> {
        if !stdin_is_tty() {
            return None;
        }
        let fd = std::io::stdin().as_raw_fd();
        let mut t = unsafe { std::mem::zeroed::<Termios>() };
        if unsafe { tcgetattr(fd, &mut t) } != 0 {
            return None;
        }
        let saved = t;
        // disable canonical mode and echo
        t.c_lflag &= !(0o10 | 0o2); // ICANON = 0x2, ECHO = 0x10 on Linux
        unsafe {
            tcsetattr(fd, 0, &t);
        }
        Some(RawGuard { saved })
    }
}

impl Drop for RawGuard {
    fn drop(&mut self) {
        let fd = std::io::stdin().as_raw_fd();
        unsafe {
            tcsetattr(fd, 0, &self.saved);
        }
    }
}
