// Configuration file (~/.ambr.toml preferred, then XDG location).
// Only boolean entries are honoured; unparsable files are ignored silently.

use std::path::PathBuf;

#[derive(Clone, Debug)]
pub struct FileCfg {
    pub regex: Option<bool>,
    pub column: Option<bool>,
    pub row: Option<bool>,
    pub binary: Option<bool>,
    pub statistics: Option<bool>,
    pub skipped: Option<bool>,
    pub interactive: Option<bool>,
    pub recursive: Option<bool>,
    pub symlink: Option<bool>,
    pub color: Option<bool>,
    pub file: Option<bool>,
    pub skip_vcs: Option<bool>,
    pub skip_gitignore: Option<bool>,
    pub fixed_order: Option<bool>,
    pub parent_ignore: Option<bool>,
    pub line_by_match: Option<bool>,
}

impl Default for FileCfg {
    fn default() -> Self {
        FileCfg {
            regex: None,
            column: None,
            row: None,
            binary: None,
            statistics: None,
            skipped: None,
            interactive: None,
            recursive: None,
            symlink: None,
            color: None,
            file: None,
            skip_vcs: None,
            skip_gitignore: None,
            fixed_order: None,
            parent_ignore: None,
            line_by_match: None,
        }
    }
}

fn config_paths() -> Vec<PathBuf> {
    let mut v = Vec::new();
    if let Ok(home) = std::env::var("HOME") {
        v.push(PathBuf::from(&home).join(".ambr.toml"));
        if let Some(dir) = xdg_config_home(&home) {
            v.push(dir.join("amber").join("ambr.toml"));
        }
    }
    v.push(PathBuf::from("/etc/amber/ambr.toml"));
    v
}

fn xdg_config_home(home: &str) -> Option<PathBuf> {
    if let Ok(x) = std::env::var("XDG_CONFIG_HOME") {
        if !x.is_empty() {
            return Some(PathBuf::from(x));
        }
    }
    Some(PathBuf::from(home).join(".config"))
}

pub fn load() -> FileCfg {
    let mut cfg = FileCfg::default();
    for p in config_paths() {
        let data = match std::fs::read(&p) {
            Ok(d) => d,
            Err(_) => continue,
        };
        let text = String::from_utf8_lossy(&data).to_string();
        parse_into(&text, &mut cfg);
        break;
    }
    cfg
}

fn parse_into(text: &str, cfg: &mut FileCfg) {
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with('[') {
            continue;
        }
        let mut it = line.splitn(2, '=');
        let key = match it.next() {
            Some(k) => k.trim(),
            None => continue,
        };
        let val = match it.next() {
            Some(v) => v.trim(),
            None => continue,
        };
        let val = val.trim_end_matches(',');
        let b = match val {
            "true" => Some(true),
            "false" => Some(false),
            _ => None,
        };
        if b.is_none() {
            continue;
        }
        let b = b.unwrap();
        match key {
            "regex" => cfg.regex = Some(b),
            "column" => cfg.column = Some(b),
            "row" => cfg.row = Some(b),
            "binary" => cfg.binary = Some(b),
            "statistics" => cfg.statistics = Some(b),
            "skipped" => cfg.skipped = Some(b),
            "interactive" => cfg.interactive = Some(b),
            "recursive" => cfg.recursive = Some(b),
            "symlink" => cfg.symlink = Some(b),
            "color" => cfg.color = Some(b),
            "file" => cfg.file = Some(b),
            "skip_vcs" => cfg.skip_vcs = Some(b),
            "skip_gitignore" => cfg.skip_gitignore = Some(b),
            "fixed_order" => cfg.fixed_order = Some(b),
            "parent_ignore" => cfg.parent_ignore = Some(b),
            "line_by_match" => cfg.line_by_match = Some(b),
            _ => {}
        }
    }
}
