use std::collections::HashSet;
use std::io::Write;
use std::path::PathBuf;
use std::sync::mpsc;
use std::sync::{Arc, Mutex};
use std::time::Instant;

const BIN_CHECK_BYTES_DEFAULT: u64 = 256;
const SIZE_PER_THREAD_DEFAULT: u64 = 1048576;

struct App {
    keyword: Vec<u8>,
    replacement: Vec<u8>,
    regex: Option<Regex>,
