}

fn err_out<W: Write>(p: Option<&mut Printer<W>>, msg: &str) {
    if let Some(pr) = p {
        if pr.cfg.color {
            let _ = pr.term.fg(RED);
        }
        let _ = pr.term.write(msg.as_bytes());
    }
}

fn build_cfg(m: &Matches, f: &config::FileCfg) -> Cfg {
    Cfg {
        color: bool_of(m, f, "color", "no-color", true),
        file: bool_of(m, f, "file", "no-file", true),
        column: bool_of(m, f, "column", "no-column", false),
        row: bool_of(m, f, "row", "no-row", false),
        interactive: bool_of(m, f, "interactive", "no-interactive", true),
    }
}

fn bool_of(m: &Matches, f: &config::FileCfg, pos: &str, neg: &str, dflt: bool) -> bool {
    if m.is_present(pos) {
        return true;
    }
    if m.is_present(neg) {
        return false;
    }
    match f.get_field(pos) {
        Some(b) => b,
        None => dflt,
    }
}

impl config::FileCfg {
    fn get_field(&self, name: &str) -> Option<bool> {
        match name {
            "color" => self.color,
            "file" => self.file,
            "column" => self.column,
            "row" => self.row,
            "interactive" => self.interactive,
            "regex" => self.regex,
            "binary" => self.binary,
            "statistics" => self.statistics,
            "skipped" => self.skipped,
            "recursive" => self.recursive,
            "symlink" => self.symlink,
            "skip_vcs" => self.skip_vcs,
            "skip_gitignore" => self.skip_gitignore,
            "fixed_order" => self.fixed_order,
            "parent_ignore" => self.parent_ignore,
            "line_by_match" => self.line_by_match,
            _ => None,
        }
    }
}

fn flag_bool(m: &Matches, f: &config::FileCfg, pos: &str, neg: &str, dflt: bool) -> bool {
    bool_of(m, f, pos, neg, dflt)
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let m = match args::parse(&argv) {
        Ok(m) => m,
        Err(e) => {
            e.print();
            std::process::exit(1);
        }
    };
    let fcfg = config::load();

    // terminals must be available
    let tout = match color::stdout_term() {
        Some(t) => t,
        None => std::process::exit(1),
    };
    let terr = match color::stderr_term() {
        Some(t) => t,
        None => std::process::exit(1),
    };

    let cfg = build_cfg(&m, &fcfg);
    let out_writer = std::io::BufWriter::with_capacity(64 * 1024, std::io::stdout());
    let mut printer = Printer {
        term: tout,
        cfg: cfg.clone(),
    };
    let mut eprinter = Printer {
        term: terr,
        cfg: cfg.clone(),
    };

    let mut rc = 0;
    match run(&m, &fcfg, &mut printer, &mut eprinter) {
        Ok(()) => {}
        Err(code) => rc = code,
    }
    // flush and reset
    let _ = printer.term.write(b"");
    let _ = std::io::stdout().flush();
    if printer.term.reset().is_err() {
        std::process::exit(1);
    }
    if eprinter.term.reset().is_err() {
        std::process::exit(1);
    }
    std::process::exit(rc);
