    let binary = flag_bool(m, f, "binary", "no-binary", false);
    let statistics = flag_bool(m, f, "statistics", "no-statistics", false);
    let skipped_out = flag_bool(m, f, "skipped", "no-skipped", false);
    let recursive = flag_bool(m, f, "recursive", "no-recursive", true);
    let symlink = flag_bool(m, f, "symlink", "no-symlink", true);
    let skip_vcs = flag_bool(m, f, "skip-vcs", "no-skip-vcs", true);
    let skip_gitignore = flag_bool(m, f, "skip-gitignore", "no-skip-gitignore", true);
    let fixed_order = flag_bool(m, f, "fixed-order", "no-fixed-order", true);
    let parent_ignore = flag_bool(m, f, "parent-ignore", "no-parent-ignore", true);
    let preserve_time = m.is_present("preserve-time");
    let line_by_match = f.line_by_match.unwrap_or(false);
    let verbose = m.is_present("verbose");

    let max_threads = m
        .value("max-threads")
        .and_then(|v| v.parse::<usize>().ok())
        .unwrap_or(20);
    let size_per_thread = m
        .value("size-per-thread")
        .and_then(|v| v.parse::<u64>().ok())
        .unwrap_or(SIZE_PER_THREAD_DEFAULT);
    let bin_check_bytes = m
        .value("bin-check-bytes")
        .and_then(|v| v.parse::<u64>().ok())
        .unwrap_or(BIN_CHECK_BYTES_DEFAULT);

    let app = App {
        keyword,
        replacement: replacement_raw.clone(),
        regex,
        cfg: Cfg {
            color: printer.cfg.color,
            file: printer.cfg.file,
            column: printer.cfg.column,
            row: printer.cfg.row,
            interactive,
        },
        interactive,
        binary,
        statistics,
        skipped_out,
        max_threads,
        size_per_thread,
        bin_check_bytes,
        fixed_order,
        preserve_time,
        line_by_match,
    };

    // paths: default "."
    let paths: Vec<String> = if m.paths.is_empty() {
        vec![".".to_string()]
    } else {
        m.paths.clone()
    };

    let mut skips: Vec<String> = Vec::new();
    let mut found_parent: Vec<String> = Vec::new();
    let mut walk_errors: Vec<String> = Vec::new();
    let mut seen: HashSet<PathBuf> = HashSet::new();
    let t_find = Instant::now();
    let files = walk::walk(
        &paths,
        &walk::WalkCfg {
            recursive,
            symlink,
            skip_vcs,
            skip_gitignore,
            parent_ignore,
        },
        &mut seen,
        &mut skips,
        &mut found_parent,
        &mut walk_errors,
    );
    let find_total = t_find.elapsed().as_secs_f64();
    let find_busy = 0u64;

    // search phase
    let t_match = Instant::now();
    let nthreads = std::cmp::max(1, std::cmp::min(app.max_threads, std::cmp::max(files.len(), 1)));
    let matcher = Arc::new(search::Matcher::new(
        &app.keyword,
        &app.replacement,
        app.regex.clone(),
    ));
    let results: Vec<Option<FileMatch>> = if nthreads <= 1 || files.is_empty() {
        let mut out = Vec::new();
        for (i, f) in files.iter().enumerate() {
            out.push(search_one(f, i, &app, &matcher, &mut skips));
        }
        out
    } else {
        let n = nthreads;
        let files_arc: Vec<PathBuf> = files.clone();
        let (tx, rx) = mpsc::channel::<(usize, Option<FileMatch>)>();
        let skips_shared = Arc::new(Mutex::new(Vec::<String>::new()));
        let mut handles = Vec::new();
        for t in 0..n {
            let tx = tx.clone();
            let app = &app;
            let matcher = matcher.clone();
            let sk = skips_shared.clone();
            let chunk: Vec<(usize, PathBuf)> = files_arc
                .iter()
                .enumerate()
                .filter(|(i, _)| i % n == t)
                .map(|(i, p)| (i, p.clone()))
                .collect();
            let appref: &'static App = unsafe { std::mem::transmute(app) };
            let h = std::thread::spawn(move || {
                for (i, f) in chunk {
                    let mut local_skips: Vec<String> = Vec::new();
                    let r = search_one(&f, i, appref, &matcher, &mut local_skips);
                    {
                        let mut g = sk.lock().unwrap();
                        g.extend(local_skips);
                    }
                    let _ = tx.send((i, r));
                }
            });
            handles.push(h);
        }
        drop(tx);
        let mut out: Vec<Option<FileMatch>> = vec![None; files.len()];
        for (i, r) in rx {
            out[i] = r;
        }
        for h in handles {
            let _ = h.join();
        }
        {
            let g = skips_shared.lock().unwrap();
            skips.extend(g.iter().cloned());
        }
        out
    };
    let match_total = t_match.elapsed().as_secs_f64();
    let match_busy: Vec<u64> = vec![0u64; nthreads];

    // sort matches (fixed order)
    let t_sort = Instant::now();
    let mut all: Vec<FileMatch> = results.into_iter().flatten().collect();
    if fixed_order {
        all.sort_by_key(|fm| fm.index);
    }
    let sort_total = t_sort.elapsed().as_secs_f64();

    // replace phase
    let t_replace = Instant::now();
    let mut all_flag = false;
    let mut quit = false;
    let _guard = if interactive {
        tty::RawGuard::new()
    } else {
        None
    };
    for fm in all.iter_mut() {
        if quit {
            break;
        }
        let disp = fm.path.to_string_lossy().to_string();
        let mut content: Vec<u8> = std::mem::take(&mut fm.data);
        let mut modified = false;
        let mut out: Vec<u8> = Vec::with_capacity(content.len());
        let mut pos = 0usize;
        let mlist: Vec<search::Found> = fm.matches.clone();
        for fnd in mlist.iter() {
            if quit {
                break;
            }
            if !all_flag && interactive {
                // display
                let line: &[u8] = &content[fnd.line_start..fnd.line_end.min(content.len())];
                let hl_start = fnd.start - fnd.line_start;
                let newline = build_newline(&content, fnd, &fnd.replacement);
                let nl_start = fnd.start - fnd.line_start;
                let _ = printer.print_match(
                    &disp,
                    fnd.line_no,
                    fnd.row,
                    line,
                    hl_start,
                    &fnd.matched,
                    &newline,
                    nl_start,
                    &fnd.replacement,
                );
                let _ = printer.term.write(b"");
                let _ = std::io::stdout().flush();
                let mut again = true;
                while again {
                    let _ = printer.print_prompt();
                    let _ = std::io::stdout().flush();
                    match display::read_answer(printer) {
                        Answer::Yes => again = false,
                        Answer::No => {
                            again = false;
                            continue_outer = true;
                        }
                        Answer::All => {
                            again = false;
                            all_flag = true;
                        }
                        Answer::Quit => {
                            again = false;
                            quit = true;
                        }
                        Answer::Again => again = true,
                        Answer::Eof => again = true,
                    }
                }
                if quit {
                    break;
                }
                if continue_outer {
                    continue_outer = false;
                    continue;
                }
            } else {
                // non interactive: replace
            }
            // apply replacement
            out.extend_from_slice(&content[pos..fnd.start]);
            out.extend_from_slice(&fnd.replacement);
            pos = fnd.end;
            modified = true;
        }
        if !quit {
            out.extend_from_slice(&content[pos..]);
        } else {
            out.extend_from_slice(&content[pos..]);
        }
        if modified && !quit {
            write_file(&fm.path, &out, preserve_time, &content);
        }
        content = out;
    }
    let replace_total = t_replace.elapsed().as_secs_f64();

    // output skips / messages
    if skipped_out {
        if eprinter.cfg.color {
            let _ = eprinter.term.fg(CYAN);
        }
        for s in skips.iter() {
            let _ = eprinter.term.write(s.as_bytes());
            let _ = eprinter.term.write(b"\n");
        }
    }
    if eprinter.cfg.color {
        let _ = eprinter.term.fg(RED);
    }
    for e in walk_errors.iter() {
        let _ = eprinter.term.write(b"Error: ");
        let _ = eprinter.term.write(e.as_bytes());
        let _ = eprinter.term.write(b"\n");
        let _ = eprinter.term.write(b"Error: ");
        let _ = eprinter.term.write(e.as_bytes());
        let _ = eprinter.term.write(b"\n");
    }
    for e in read_errors.iter() {
        let _ = eprinter.term.write(e.as_bytes());
        let _ = eprinter.term.write(b"\n");
    }
    for s in found_parent.iter() {
        let _ = eprinter.term.write(s.as_bytes());
        let _ = eprinter.term.write(b"\n");
    }
    if statistics {
        let _ = stats::print(
            &mut eprinter.term,
            &stats::Timings {
                max_threads,
                find_busy,
                find_total,
                match_busy,
                match_total,
                sort_busy: 0,
                sort_total,
                replace_busy: 0,
                replace_total,
            },
        );
    }
    Ok(())
}

static mut continue_outer: bool = false;

fn build_newline(content: &[u8], fnd: &search::Found, replacement: &[u8]) -> Vec<u8> {
    let mut v: Vec<u8> = Vec::with_capacity(content.len());
    v.extend_from_slice(&content[fnd.line_start..fnd.start]);
    v.extend_from_slice(replacement);
    v.extend_from_slice(&content[fnd.end..fnd.line_end.min(content.len())]);
    v
}

fn write_file(path: &PathBuf, data: &[u8], preserve_time: bool, orig: &[u8]) {
    use std::os::unix::fs::MetadataExt;
    let meta = std::fs::metadata(path).ok();
    if let Ok(m) = std::fs::metadata(path) {
        let _ = std::fs::set_permissions(path, std::os::unix::fs::PermissionsExt::from_mode(
            (m.permissions().mode() | 0o200) & 0o7777,
        ));
    }
    let r = std::fs::write(path, data);
    if let Some(m) = meta {
        let _ = std::fs::set_permissions(path, m.permissions());
        if preserve_time {
            let _ = std::fs::set_file_times(path, m.accessed().ok(), m.modified().ok());
        }
    }
    let _ = orig;
}

fn search_one(
    path: &PathBuf,
    index: usize,
    app: &App,
    matcher: &search::Matcher,
    skips: &mut Vec<String>,
) -> Option<FileMatch> {
    let data = match std::fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            READ_ERRORS.lock().unwrap().push(format!(
                "Error: {} @ {:?}\n\n",
                e,
                path.to_string_lossy().to_string()
            ));
            return None;
        }
    };
    // binary check
    if !app.binary {
        let n = std::cmp::min(app.bin_check_bytes as usize, data.len());
        if memchr::memchr(b'\0', &data[..n]).is_some() {
            skips.push(format!(
                "Skip (binary)    : {:?}",
                path.to_string_lossy().to_string()
            ));
            return None;
        }
    }
    let chunk_line = 0usize;
    let mut matches = Vec::new();
    if data.len() as u64 > app.size_per_thread && app.size_per_thread > 0 {
        // split into chunks at line boundaries
        let mut start = 0usize;
        let mut line_off = 0usize;
        let mut covered_end = 0usize;
        while start < data.len() {
            let mut end = std::cmp::min(start + app.size_per_thread as usize, data.len());
            if end < data.len() {
                // extend to the end of the line
                if let Some(p) = memchr::memchr(b'\n', &data[end..]) {
                    end = end + p + 1;
                } else {
                    end = data.len();
                }
            }
            if start >= covered_end {
                let mts = matcher.find_all(&data[start..end], line_off, &app.replacement);
                for mut f in mts {
                    f.start += start;
                    f.end += start;
                    f.line_start += start;
                    f.line_end += start;
                    matches.push(f);
                }
                covered_end = end;
            } else {
                // overlapping chunk: only take matches beyond covered_end
                let mts = matcher.find_all(&data[start..end], line_off, &app.replacement);
                for mut f in mts {
                    if f.start + start < covered_end {
                        continue;
                    }
                    f.start += start;
                    f.end += start;
                    f.line_start += start;
                    f.line_end += start;
                    matches.push(f);
                }
            }
            // advance
            line_off += memchr::memchr_iter(b'\n', &data[start..end]).count();
            start = end;
        }
    } else {
        matches = matcher.find_all(&data, 0, &app.replacement);
    }
    if matches.is_empty() {
        return None;
    }
    Some(FileMatch {
        index,
        path: path.clone(),
        matches,
        data,
    })
}

static READ_ERRORS: std::sync::Mutex<Vec<String>> = std::sync::Mutex::new(Vec::new());
